Cliente  1 ---- N  Pedido  1 ---- N  ItemPedido  N ---- 1  Produto

Lê-se: um cliente tem muitos pedidos; um pedido tem muitos itens;
cada item aponta para um produto.

CREATE TABLE pedido (
  id          SERIAL PRIMARY KEY,
  cliente_id  INT NOT NULL REFERENCES cliente(id),
  status      TEXT NOT NULL,
  criado_em   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE item_pedido (
  id          SERIAL PRIMARY KEY,
  pedido_id   INT NOT NULL REFERENCES pedido(id) ON DELETE CASCADE,
  produto_id  INT NOT NULL REFERENCES produto(id),
  quantidade  INT NOT NULL CHECK (quantidade > 0),
  preco_unit  NUMERIC(12,2) NOT NULL
);

