CREATE TABLE ticket_status_historico (
  id              SERIAL PRIMARY KEY,
  ticket_id       INT NOT NULL REFERENCES ticket(id) ON DELETE CASCADE,
  status_anterior TEXT,
  status_novo     TEXT NOT NULL,
  usuario_id      INT NOT NULL REFERENCES usuario(id),
  mudado_em       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_historico_ticket ON ticket_status_historico (ticket_id, mudado_em DESC);

